getPSDETreeNodeDataItems.scriptCode:
var type = data.type ? data.type : "";
var codeValue = "";
var codeItem = "";

if (type && type !== "") {
    console.log("绘制类型图标");
    var codelisttag = "ai__entity_types";
    const app = await ibiz.hub.getApp(context.srfappid);
    const codelist = app.codeList;
    codeItem = await codelist.getItem(codelisttag, type, context, "");
    codeValue = codeItem.text;

    if (codeItem.icon) {
        // icon 是字符串，需要先解析为 JSON 对象
        let iconArray;
        try {
            iconArray = JSON.parse(codeItem.icon);
        } catch (e) {
            console.error("解析 icon 字符串失败:", e);
            return codeValue; // 解析失败时回退到文本
        }

        if (Array.isArray(iconArray) && iconArray.length > 0) {
            const icon = iconArray[0];
            const appid = context.srfappid;
            const baseUrl = ibiz.env.baseUrl;
            const fileId = icon.id;
            const folder = icon.folder;
            const url = `${baseUrl}/${appid}/ibizutil/download/${folder}/${fileId}`;
            const imgstr = `<img alt="${codeValue}" src="${url}">`;
            return `<div class="ibiz-code-list__item" style="height: 36px;line-height: 36px;">
                        <div class="ibiz-icon" style="height: 100%;padding-right: 8px;">
                            ${imgstr}
                        </div>
                    </div>`;
        }
    }
}

return codeValue;

